input.content:
import { after } from 'next/server'

interface AnalyticsData {
  page: string
  timestamp: string
  userAgent?: string
}

async function logToAnalytics(data: AnalyticsData): Promise<void> {
  console.log('[Analytics] Logging page view:', data)

  await new Promise(resolve => setTimeout(resolve, 100))
}

export default async function WelcomePage(): Promise<JSX.Element> {
  const pageData: AnalyticsData = {
    page: '/welcome',
    timestamp: new Date().toISOString(),
  }

  after(async () => {
    await logToAnalytics(pageData)
  })

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Welcome!</h1>
      <p>Thanks for visiting our page.</p>
    </main>
  )
}

